#!/usr/bin/env python3
with open("app/dashboard/page.tsx") as f:
    content = f.read()
start_marker = '      <div className="max-w-6xl mx-auto space-y-8">'
start_idx = content.find(start_marker)
end_marker = "\n      <Sidebar\n"
end_idx = content.find(end_marker)
print("start", start_idx, "end", end_idx)
if start_idx > -1 and end_idx > -1:
    new_block = '      <div className="max-w-5xl mx-auto px-4 md:px-8 lg:px-10 space-y-6 md:space-y-8" dir="rtl">\n        <section aria-label="ترحيب" className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-[#1b2140] via-[#161b36] to-[#0e1222] border border-white/[0.08] p-6 md:p-8 lg:p-10">\n          <div className="absolute top-0 left-0 h-48 w-48 -translate-x-1/4 -translate-y-1/3 rounded-full bg-amber-400/10 blur-3xl" />\n          <div className="absolute bottom-0 right-0 h-40 w-40 translate-x-1/3 translate-y-1/3 rounded-full bg-rose-400/10 blur-3xl" />\n          <div className="relative z-10 flex flex-col md:flex-row md:items-center md:justify-between gap-6">\n            <div className="flex-1">\n              <div className="flex items-center gap-2 mb-3"><span className="inline-flex items-center gap-1.5 rounded-full bg-amber-400/15 text-amber-300 px-2.5 py-0.5 text-xs font-bold tracking-wide border border-amber-400/20">✨ المستوى {level}</span><span className="inline-flex items-center gap-1 rounded-full bg-rose-400/15 text-rose-300 px-2.5 py-0.5 text-xs font-bold tracking-wide border border-rose-400/20">🔥 {streak} يوم متتالي</span></div>\n              <h1 className="text-3xl md:text-4xl font-extrabold text-[#f2f4fa] tracking-tight leading-[1.1] mb-2">أهلاً بك مجددًا، <span className="text-amber-300">{displayName || "زائر"}</span> 👋</h1>\n              <p className="text-[#9aa3bb] text-base md:text-lg max-w-xl leading-relaxed">{headerSubtitle || "جاهز تكمل رحلتك التعليمية؟"}</p>\n            </div>\n            <div className="flex md:flex-col gap-3 md:items-end shrink-0"><button onClick={() => { const el = document.getElementById("day-" + currentDayNumber); el?.scrollIntoView({behavior:"smooth",block:"center"}); }} className="inline-flex items-center gap-2 rounded-2xl bg-amber-400 text-[#0b0e1a] px-6 py-3 font-extrabold shadow-lg shadow-amber-400/20 hover:bg-amber-300 transition-colors text-base">أكمل التعلم ←</button><button onClick={handleOpenAiAssistant} className="inline-flex items-center gap-2 rounded-2xl bg-white/[0.06] text-[#e4e8f8] border border-white/[0.10] px-6 py-3 font-bold hover:bg-white/[0.10] transition-colors text-base">المساعد الذكي</button></div>\n          </div>\n        </section>\n\n        <section aria-label="إحصائيات سريعة" className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4" dir="rtl">\n          {[{label:"الن points",value:xp.toLocaleString("ar-EG"),sub:"مكتسب",icon:"⚡"},{label:"سلسلة التعلم",value:String(streak),sub:"يوم متتالي",icon:"🔥"},{label:"دروس مكتملة",value:`${completedCount}/${days.length}`,sub:`تقدم ${days.length>0?Math.round((completedCount/days.length)*100):0}%`,icon:"📘"}].map(s=> (<div key={s.label} className="rounded-2xl bg-[#13182b]/70 border border-white/[0.07] p-4 md:p-5 backdrop-blur-sm hover:border-white/[0.12] transition-colors"><div className="inline-flex h-9 w-9 items-center justify-center rounded-xl bg-amber-400/10 mb-3 text-sm font-bold">{s.icon}</div><div className="text-2xl md:text-3xl font-extrabold text-[#f0f2fa] leading-none mb-1">{s.value}</div><div className="text-xs font-medium text-[#8894ae] mb-0.5">{s.label}</div><div className="text-[11px] text-[#6b799f]">{s.sub}</div></div>))}\n        </section>\n\n        <section aria-label="استمر في التعلم" dir="rtl"><div className="rounded-3xl overflow-hidden bg-gradient-to-br from-[#1b2140] via-[#161b36] to-[#111636] border border-white/[0.08] shadow-2xl shadow-black/40"><div className="p-6 md:p-8 lg:p-10"><div className="flex items-center gap-2 mb-4"><span className="h-2 w-2 rounded-full bg-amber-400 animate-pulse" /><h2 className="text-xl md:text-2xl font-extrabold text-[#f2f4fa] tracking-tight">استمر في التعلم</h2></div><div className="flex flex-col lg:flex-row gap-6 lg:gap-10 items-start"><div className="flex-1 min-w-0"><div className="text-xs font-bold text-amber-300 tracking-wide mb-1">{config?.subject || "دورة نشطة"}</div><h3 className="text-2xl md:text-3xl font-extrabold text-[#f2f4fa] mb-1 leading-snug">{days[currentDayNumber-1]?.title || "الدرس الحالي"}</h3><p className="text-[#8894ae] text-sm md:text-base mb-4">{days[currentDayNumber-1]?.topic || "استمر في بناء معرفتك."}</p><div className="w-full h-3 rounded-full bg-[#0a0d18] overflow-hidden mb-2"><div className="h-full rounded-full bg-gradient-to-r from-amber-300 via-amber-400 to-amber-200" style={{width:`${Math.round(overallProgress)}%`}} /></div><div className="text-xs font-bold text-[#8894ae]">تقدم الخطة: {Math.round(overallProgress)}%</div></div><div className="flex lg:items-center gap-3 lg:shrink-0"><button onClick={() => { const el = document.getElementById("day-"+currentDayNumber); el?.scrollIntoView({behavior:"smooth",block:"center"}); }} className="inline-flex items-center gap-2 rounded-2xl bg-amber-400 text-[#080b14] px-6 py-3.5 font-extrabold shadow-lg shadow-amber-400/20 hover:bg-amber-300 transition text-base">▶ أكمل الدرس</button></div></div></div></div></section>\n\n        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 md:gap-8"><div className="lg:col-span-2 space-y-6 md:space-y-8"><section aria-label="خطة اليوم" dir="rtl"><div className="rounded-3xl bg-[#13182b]/70 border border-white/[0.07] p-6 md:p-7 backdrop-blur-sm"><div className="flex items-center justify-between mb-5"><h2 className="text-xl font-extrabold text-[#f2f4fa] tracking-tight">خطة اليوم</h2><button onClick={()=>alert("إضافة")} className="text-xs font-bold text-amber-300 hover:text-amber-200">+ إضافة</button></div><div className="flex flex-col gap-2">{days.slice(0,3).map((d,i)=>(<button key={d.day} className="group flex items-center gap-3 rounded-2xl px-4 py-3.5 text-right bg-white/[0.03] border border-white/[0.06] hover:border-white/[0.12] transition text-sm font-medium"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-white/[0.06] text-[#8894ae] text-xs">{i+1}</span><div className="min-w-0 flex-1"><div className="font-bold text-[#f0f2fa] truncate">{d.title}</div><div className="text-[11px] text-[#6b799f]">{d.topic}</div></div><span className="text-xs text-[#6b799f]">~20 دقيقة</span></button>))}</div></div></section><section aria-label="مساعدك الذكي" dir="rtl"><div className="rounded-3xl bg-gradient-to-br from-[#181e3a]/80 to-[#111636]/80 border border-white/[0.08] p-6 md:p-7 backdrop-blur-sm relative overflow-hidden"><div className="absolute -top-10 -left-10 h-32 w-32 rounded-full bg-amber-400/10 blur-3xl pointer-events-none" /><div className="relative z-10"><div className="flex items-center gap-2 mb-3"><span className="h-2 w-2 rounded-full bg-amber-400 animate-pulse" /><h2 className="text-lg font-extrabold text-[#f2f4fa] tracking-tight">مساعدك الذكي</h2></div><p className="text-[#8894ae] text-sm md:text-base leading-relaxed mb-4">بناءً على تقدمك ({Math.round(overallProgress)}%)، أنصحك بمتابعة درس جديد ومراجعة ما تعلمته.</p><div className="flex flex-wrap gap-2 mb-4"><button onClick={() => { const el = document.getElementById("day-"+currentDayNumber); el?.scrollIntoView({behavior:"smooth",block:"center"}); }} className="rounded-xl bg-white/[0.06] text-[#e4e8f8] border border-white/[0.08] px-3.5 py-2 text-xs font-bold hover:bg-white/[0.10]">استمر في التعلم</button><button onClick={() => alert("مراجعة")} className="rounded-xl bg-white/[0.06] text-[#e4e8f8] border border-white/[0.08] px-3.5 py-2 text-xs font-bold hover:bg-white/[0.10]">راجع اليوم</button></div><button onClick={handleOpenAiAssistant} className="inline-flex items-center gap-2 rounded-2xl bg-amber-400 text-[#080b14] px-5 py-2.5 font-extrabold text-sm hover:bg-amber-300 transition shadow-md shadow-amber-400/20">✨ فتح المساعد ←</button></div></div></section></div><div className="space-y-6 md:space-y-8"><section aria-label="تقدم التعلم" dir="rtl"><div className="rounded-3xl bg-[#13182b]/70 border border-white/[0.07] p-6 md:p-7 backdrop-blur-sm"><h2 className="text-xl font-extrabold text-[#f2f4fa] mb-5 tracking-tight">تقدم التعلم</h2><div className="grid grid-cols-1 md:grid-cols-2 gap-4">{[{label:"التقدم الأسبوعي",value:Math.round(overallProgress),color:"from-amber-300 to-amber-500"},{label:"سلسلة التعلم",value:Math.min(streak*14,100),color:"from-rose-300 to-rose-500"},{label:"دروس مكتملة",value:Math.min(completedCount*10,100),color:"from-emerald-300 to-emerald-500"}].map(b=>(<div key={b.label} className="rounded-2xl bg-[#0b1020]/60 border border-white/[0.06] p-4"><div className="text-sm font-bold text-[#e4e8f8] mb-2">{b.label}</div><div className="w-full h-2.5 rounded-full bg-[#0a0d18] overflow-hidden mb-1.5"><div className={`h-full rounded-full bg-gradient-to-r ${b.color}`} style={{width:`${b.value}%`}} /></div><div className="text-xs text-[#6b799f]">{b.value}%</div></div>))}</div></div></section></div></div><section aria-label="أدوات سريعة" dir="rtl"><div className="rounded-3xl bg-[#13182b]/70 border border-white/[0.07] p-6 md:p-7 backdrop-blur-sm"><div className="flex items-center justify-between mb-5"><h2 className="text-xl font-extrabold text-[#f2f4fa] tracking-tight">أدوات سريعة</h2><button onClick={() => alert("إنشاء خطة")} className="inline-flex items-center gap-1.5 rounded-xl bg-amber-400/15 text-amber-300 px-3 py-1.5 text-xs font-bold border border-amber-400/20 hover:bg-amber-400/25">+ إنشاء خطة</button></div><div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">{["وكلاء الذكاء","المخطط","التقويم","الملاحظات","مساحة العمل","القرآن الكريم"].map(t=>(<a key={t} href="#" className="group flex flex-col items-center gap-2.5 rounded-2xl bg-[#0b1020]/60 border border-white/[0.06] p-4 hover:border-white/[0.12] hover:bg-[#111636] transition text-center"><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-violet-400/10 text-violet-300"><Bot size={20} /></span><span className="text-xs font-bold text-[#e4e8f8]">{t}</span></a>))}</div><div className="flex gap-3 mt-4"><button onClick={() => setIsEmergencyMode((e)=>!e)} className="flex-1 rounded-2xl bg-rose-400/10 text-rose-300 border border-rose-400/20 px-4 py-3 text-xs font-extrabold hover:bg-rose-400/20 transition">🛡 وضع الطوارئ</button><button onClick={() => alert("مساعدة")} className="flex-1 rounded-2xl bg-white/[0.05] text-[#8894ae] border border-white/[0.08] px-4 py-3 text-xs font-extrabold hover:text-[#f2f4fa] transition">❓ مساعدة</button></div></div></section>\n      </div>'
    content = content[:start_idx] + new_block + content[end_idx:]
    with open("app/dashboard/page.tsx", "w") as f:
        f.write(content)
    print("replaced", start_idx, end_idx)
else:
    print("markers missing")
